npx tsc --noEmit -p . && echo TSC_OK && cat > /tmp/chk.test.ts <<'EOF'
EOF
node --input-type=module -e '
import fs from "fs";
const s=fs.readFileSync("test/fixtures/users.ts","utf8");
const ids=[...s.matchAll(/id: "([^"]+)"/g)].map(m=>m[1]);
const em=[...s.matchAll(/email: "([^"]+)"/g)].map(m=>m[1]);
const c=[...s.matchAll(/createdAt: new Date\("([^"]+)"\)/g)].map(m=>Date.parse(m[1]));
const u=[...s.matchAll(/updatedAt: new Date\("([^"]+)"\)/g)].map(m=>Date.parse(m[1]));
const v4=ids.every(i=>/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(i));
printf=console.log;
printf("count",ids.length,"uniqIds",new Set(ids).size,"uniqEmails",new Set(em).size,"v4",v4,"order",c.every((x,i)=>u[i]>=x&&!isNaN(x)));
' && npm test 2>&1 | tail -5

